using UnityEngine;
using System.Collections.Generic;

// Tanviir texture pack blockset ("Tanviir: <name>"), built from the pack atlas in
// Resources/BlockSet/Atlases/TanviirPack (generated by TanviirPackImport in the Editor).
// The blocks are appended after every older block, so existing save IDs never move.
// The older hand-made "Tanviir ..." palette is retired: its IDs stay valid for old saves,
// but those blocks are hidden from inventory/designer and now render with pack textures.
public static class TanviirPackBlocks {
    public const string Prefix = "Tanviir: ";
    const string AtlasPath = "BlockSet/Atlases/TanviirPack/Tanviir Pack Atlas";
    const string IndexPath = "BlockSet/Atlases/TanviirPack/Tanviir Pack Atlas Index";

    public static readonly string[] DyeTex = { "white", "orange", "magenta", "light_blue", "yellow", "lime", "pink", "gray", "silver", "cyan", "purple", "blue", "brown", "green", "red", "black" };
    public static readonly string[] DyeName = { "White", "Orange", "Magenta", "Light Blue", "Yellow", "Lime", "Pink", "Gray", "Light Gray", "Cyan", "Purple", "Blue", "Brown", "Green", "Red", "Black" };
    public static readonly string[] Wood = { "Oak", "Spruce", "Birch", "Jungle" };
    // Legacy stone slab materials (meta 0-7) and the wooden slabs (meta 0-3).
    public static readonly string[] StoneSlab = { "Stone", "Sandstone", "Wooden", "Cobblestone", "Brick", "Stone Brick", "Nether Brick", "Quartz" };

    struct Tex { public Rect rect; public bool alpha; }
    static readonly Dictionary<string, Tex> tex = new Dictionary<string, Tex>();
    static Material solid, cutout;
    static BlockSet set;

    public static void Ensure(BlockSet blockSet) {
        set = blockSet;
        Texture2D atlas = Resources.Load<Texture2D>(AtlasPath);
        TextAsset index = Resources.Load<TextAsset>(IndexPath);
        if(atlas == null || index == null) { Debug.LogWarning("TANVIIR PACK: atlas missing; Tanviir pack blocks skipped."); return; }
        ReadIndex(index.text);
        Shader s = Shader.Find("VoxelEngine/Diffuse"); if(s == null) s = Shader.Find("Standard");
        Shader a = Shader.Find("VoxelEngine/Alpha-Diffuse_cull_off"); if(a == null) a = Shader.Find("VoxelEngine/Alpha-Diffuse"); if(a == null) a = s;
        solid = new Material(s) { name = "Tanviir Pack Material", mainTexture = atlas, hideFlags = HideFlags.DontSave };
        cutout = new Material(a) { name = "Tanviir Pack Cutout Material", mainTexture = atlas, hideFlags = HideFlags.DontSave };

        int before = set.Count;
        // Natural blocks
        Cube("Stone", "stone"); Cube3("Grass Block", "grass_top", "grass_side_tinted", "dirt"); Cube("Dirt", "dirt");
        Cube("Cobblestone", "cobblestone"); Cube("Mossy Cobblestone", "cobblestone_mossy"); Cube("Bedrock", "bedrock");
        Cube("Sand", "sand"); Cube("Gravel", "gravel"); Cube("Clay", "clay"); Cube("Snow", "snow"); Cube("Ice", "ice");
        Cube3("Mycelium", "mycelium_top", "mycelium_side", "dirt"); Cube3("Farmland", "farmland_wet", "dirt", "dirt");
        Cube("Netherrack", "netherrack"); Cube("Soul Sand", "soul_sand"); Cube("End Stone", "end_stone"); Cube("Obsidian", "obsidian");
        foreach(string w in Wood) {
            string t = w.ToLowerInvariant();
            Cube(w + " Planks", "planks_" + t); Cube3(w + " Log", "log_" + t + "_top", "log_" + t, "log_" + t + "_top"); Cube(w + " Leaves", "leaves_" + t);
        }
        // Ores and mineral blocks
        Cube("Coal Ore", "coal_ore"); Cube("Iron Ore", "iron_ore"); Cube("Gold Ore", "gold_ore"); Cube("Lapis Ore", "lapis_ore");
        Cube("Diamond Ore", "diamond_ore"); Cube("Redstone Ore", "redstone_ore"); Cube("Emerald Ore", "emerald_ore"); Cube("Quartz Ore", "quartz_ore");
        Cube("Coal Block", "coal_block"); Cube("Iron Block", "iron_block"); Cube("Gold Block", "gold_block"); Cube("Lapis Block", "lapis_block");
        Cube("Diamond Block", "diamond_block"); Cube("Emerald Block", "emerald_block"); Cube("Redstone Block", "redstone_block");
        // Building blocks
        Cube3("Sandstone", "sandstone_top", "sandstone_normal", "sandstone_bottom"); Cube3("Chiseled Sandstone", "sandstone_top", "sandstone_carved", "sandstone_bottom");
        Cube3("Smooth Sandstone", "sandstone_top", "sandstone_smooth", "sandstone_bottom");
        Cube3("Double Stone Slab", "stone_slab_top", "stone_slab_side", "stone_slab_top"); Cube("Smooth Stone", "stone_slab_top");
        Cube("Bricks", "brick"); Cube("Stone Bricks", "stonebrick"); Cube("Mossy Stone Bricks", "stonebrick_mossy");
        Cube("Cracked Stone Bricks", "stonebrick_cracked"); Cube("Chiseled Stone Bricks", "stonebrick_carved"); Cube("Nether Bricks", "nether_brick");
        Cube3("Quartz Block", "quartz_block_top", "quartz_block_side", "quartz_block_bottom"); Cube3("Chiseled Quartz", "quartz_block_chiseled_top", "quartz_block_chiseled", "quartz_block_chiseled_top");
        Cube3("Quartz Pillar", "quartz_block_lines_top", "quartz_block_lines", "quartz_block_lines_top");
        Cube("Hardened Clay", "hardened_clay");
        for(int i = 0; i < 16; i++) Cube(DyeName[i] + " Wool", "wool_colored_" + DyeTex[i]);
        for(int i = 0; i < 16; i++) Cube(DyeName[i] + " Stained Clay", "hardened_clay_stained_" + DyeTex[i]);
        Cube("Glass", "glass");
        for(int i = 0; i < 16; i++) Cube(DyeName[i] + " Stained Glass", "glass_" + DyeTex[i]);
        Cube("Glowstone", "glowstone", 15); Cube("Sponge", "sponge"); Cube3("Melon", "melon_top", "melon_side", "melon_top");
        Cube("Brown Mushroom Block", "mushroom_block_skin_brown"); Cube("Red Mushroom Block", "mushroom_block_skin_red"); Cube("Mushroom Stem", "mushroom_block_skin_stem");
        // Functional / decorative cubes (front face follows the voxel direction)
        Cube3("TNT", "tnt_top", "tnt_side", "tnt_bottom"); Cube3("Bookshelf", "planks_oak", "bookshelf", "planks_oak");
        CubeFront("Crafting Table", "crafting_table_top", "crafting_table_side", "planks_oak", "crafting_table_front");
        CubeFront("Furnace", "furnace_top", "furnace_side", "furnace_top", "furnace_front_off");
        CubeFront("Lit Furnace", "furnace_top", "furnace_side", "furnace_top", "furnace_front_on", 13);
        CubeFront("Dispenser", "furnace_top", "furnace_side", "furnace_top", "dispenser_front_horizontal");
        CubeFront("Dropper", "furnace_top", "furnace_side", "furnace_top", "dropper_front_horizontal");
        CubeFront("Pumpkin", "pumpkin_top", "pumpkin_side", "pumpkin_top", "pumpkin_face_off");
        CubeFront("Jack o'Lantern", "pumpkin_top", "pumpkin_side", "pumpkin_top", "pumpkin_face_on", 15);
        Cube("Note Block", "noteblock"); Cube3("Jukebox", "jukebox_top", "jukebox_side", "jukebox_side"); Cube("Command Block", "command_block");
        Cube3("Piston", "piston_top_normal", "piston_side", "piston_bottom"); Cube3("Sticky Piston", "piston_top_sticky", "piston_side", "piston_bottom");
        Cube("Redstone Lamp", "redstone_lamp_off"); Cube("Lit Redstone Lamp", "redstone_lamp_on", 15);
        Cube("Mob Spawner", "mob_spawner"); Cube3("Cactus", "cactus_top", "cactus_side", "cactus_bottom");
        Cube3("Enchanting Table", "enchanting_table_top", "enchanting_table_side", "enchanting_table_bottom");
        Cube3("End Portal Frame", "endframe_top", "endframe_side", "end_stone"); Cube("Dragon Egg", "dragon_egg"); Cube("Beacon", "beacon", 15);
        Cube3("Cauldron", "cauldron_top", "cauldron_side", "cauldron_bottom"); Cube3("Hopper", "hopper_top", "hopper_outside", "hopper_outside");
        Cube3("Anvil", "anvil_top_damaged_0", "anvil_base", "anvil_base"); Cube("Nether Portal", "portal", 11);
        Fluid("Lava", "lava_still", 15);
        // Plants (crossed quads)
        foreach(string w in Wood) Cross(w + " Sapling", "sapling_" + w.ToLowerInvariant());
        Cross("Tall Grass", "tallgrass"); Cross("Fern", "fern"); Cross("Dead Bush", "deadbush"); Cross("Dandelion", "flower_dandelion"); Cross("Rose", "flower_rose");
        Cross("Brown Mushroom", "mushroom_brown"); Cross("Red Mushroom", "mushroom_red"); Cross("Sugar Cane", "reeds"); Cross("Wheat", "wheat_stage_7");
        Cross("Carrots", "carrots_stage_3"); Cross("Potatoes", "potatoes_stage_3"); Cross("Nether Wart", "nether_wart_stage_2"); Cross("Cobweb", "web");
        Cross("Fire", "fire_layer_0", 15); Cross("Melon Stem", "melon_stem_disconnected"); Cross("Pumpkin Stem", "pumpkin_stem_disconnected"); Cross("Brewing Stand", "brewing_stand");
        // Stairs, fences, walls, panes
        foreach(string w in Wood) Stair(w + " Stairs", "planks_" + w.ToLowerInvariant());
        Stair("Cobblestone Stairs", "cobblestone"); Stair("Brick Stairs", "brick"); Stair("Stone Brick Stairs", "stonebrick");
        Stair("Nether Brick Stairs", "nether_brick"); Stair("Sandstone Stairs", "sandstone_normal"); Stair("Quartz Stairs", "quartz_block_side");
        Fence("Oak Fence", "planks_oak"); Fence("Nether Brick Fence", "nether_brick"); Fence("Cobblestone Wall", "cobblestone"); Fence("Mossy Cobblestone Wall", "cobblestone_mossy");
        Pane("Glass Pane", "glass"); Pane("Iron Bars", "iron_bars");
        for(int i = 0; i < 16; i++) Pane(DyeName[i] + " Stained Glass Pane", "glass_" + DyeTex[i]);
        // Slabs: bottom and upper half
        string[][] slabTex = {
            new[] { "stone_slab_top", "stone_slab_side" }, new[] { "sandstone_top", "sandstone_normal" }, new[] { "planks_oak", "planks_oak" }, new[] { "cobblestone", "cobblestone" },
            new[] { "brick", "brick" }, new[] { "stonebrick", "stonebrick" }, new[] { "nether_brick", "nether_brick" }, new[] { "quartz_block_top", "quartz_block_side" } };
        for(int i = 0; i < StoneSlab.Length; i++) {
            Shape(StoneSlab[i] + " Slab", TanviirPackBlock.Kind.SlabBottom, slabTex[i][0], slabTex[i][1], slabTex[i][0]);
            Shape("Upper " + StoneSlab[i] + " Slab", TanviirPackBlock.Kind.SlabTop, slabTex[i][0], slabTex[i][1], slabTex[i][0]);
        }
        foreach(string w in Wood) {
            string t = "planks_" + w.ToLowerInvariant();
            Shape(w + " Slab", TanviirPackBlock.Kind.SlabBottom, t, t, t); Shape("Upper " + w + " Slab", TanviirPackBlock.Kind.SlabTop, t, t, t);
        }
        // Thin shapes
        Shape("Oak Door Lower", TanviirPackBlock.Kind.Panel, "door_wood_lower", "door_wood_lower", "door_wood_lower");
        Shape("Oak Door Upper", TanviirPackBlock.Kind.Panel, "door_wood_upper", "door_wood_upper", "door_wood_upper");
        Shape("Iron Door Lower", TanviirPackBlock.Kind.Panel, "door_iron_lower", "door_iron_lower", "door_iron_lower");
        Shape("Iron Door Upper", TanviirPackBlock.Kind.Panel, "door_iron_upper", "door_iron_upper", "door_iron_upper");
        Shape("Ladder", TanviirPackBlock.Kind.Panel, "ladder", "ladder", "ladder");
        Shape("Vines", TanviirPackBlock.Kind.Panel, "vine", "vine", "vine");
        Shape("Wall Sign", TanviirPackBlock.Kind.Panel, "planks_oak", "planks_oak", "planks_oak");
        Shape("Open Trapdoor", TanviirPackBlock.Kind.Panel, "trapdoor", "trapdoor", "trapdoor");
        Shape("Trapdoor", TanviirPackBlock.Kind.Trapdoor, "trapdoor", "trapdoor", "trapdoor");
        for(int i = 0; i < 16; i++) Shape(DyeName[i] + " Carpet", TanviirPackBlock.Kind.Carpet, "wool_colored_" + DyeTex[i], "wool_colored_" + DyeTex[i], "wool_colored_" + DyeTex[i]);
        Shape("Snow Layer", TanviirPackBlock.Kind.SnowLayer, "snow", "snow", "snow");
        Shape("Stone Pressure Plate", TanviirPackBlock.Kind.Carpet, "stone", "stone", "stone");
        Shape("Wooden Pressure Plate", TanviirPackBlock.Kind.Carpet, "planks_oak", "planks_oak", "planks_oak");
        Shape("Gold Pressure Plate", TanviirPackBlock.Kind.Carpet, "gold_block", "gold_block", "gold_block");
        Shape("Iron Pressure Plate", TanviirPackBlock.Kind.Carpet, "iron_block", "iron_block", "iron_block");
        Shape("Lily Pad", TanviirPackBlock.Kind.Flat, "waterlily", "waterlily", "waterlily");
        Shape("Redstone Wire", TanviirPackBlock.Kind.Flat, "redstone_dust_cross", "redstone_dust_cross", "redstone_dust_cross");
        Shape("Repeater", TanviirPackBlock.Kind.Repeater, "repeater_off", "stone_slab_top", "stone_slab_top");
        Shape("Comparator", TanviirPackBlock.Kind.Repeater, "comparator_off", "stone_slab_top", "stone_slab_top");
        Shape("Torch", TanviirPackBlock.Kind.Torch, "torch_on", "torch_on", "torch_on", 14);
        Shape("Redstone Torch", TanviirPackBlock.Kind.Torch, "redstone_torch_on", "redstone_torch_on", "redstone_torch_on", 7);
        Shape("Cake", TanviirPackBlock.Kind.Cake, "cake_top", "cake_side", "cake_bottom");
        Shape("Bed Foot", TanviirPackBlock.Kind.Bed, "bed_feet_top", "bed_feet_side", "planks_oak");
        Shape("Bed Head", TanviirPackBlock.Kind.Bed, "bed_head_top", "bed_head_side", "planks_oak");

        int retired = RetireOldPalette();
        Debug.Log("TANVIIR PACK: " + (set.Count - before) + " texture-pack blocks appended (" + tex.Count + " textures); " + retired + " old Tanviir blocks retired.");
    }

    // ------------------------------------------------------------------ helpers
    static void ReadIndex(string text) {
        tex.Clear();
        foreach(string line in text.Split('\n')) {
            if(line.Length == 0 || line[0] == '#') continue;
            string[] p = line.Trim().Split(' ');
            if(p.Length < 5) continue;
            float u, v, w, h;
            if(!float.TryParse(p[1], System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out u)) continue;
            float.TryParse(p[2], System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out v);
            float.TryParse(p[3], System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out w);
            float.TryParse(p[4], System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out h);
            tex[p[0]] = new Tex { rect = new Rect(u, v, w, h), alpha = p.Length > 5 && p[5] == "1" };
        }
    }
    static bool Has(string t) { return tex.ContainsKey(t); }
    static bool Alpha(params string[] t) { foreach(string s in t) { Tex x; if(tex.TryGetValue(s, out x) && x.alpha) return true; } return false; }
    static Face F(string t, Material m) {
        Tex x; if(!tex.TryGetValue(t, out x) && !tex.TryGetValue("stone", out x)) x.rect = new Rect(0, 0, 1, 1);
        return new Face { material = m, rect = x.rect };
    }
    static bool Exists(string name) { return set.FindBlock(Prefix + name) != null; }
    static T New<T>(string name, int glow) where T : Block {
        T b = ScriptableObject.CreateInstance<T>(); b.name = Prefix + name; b.hideFlags = HideFlags.DontSave; b.glow = glow; return b;
    }
    static void Cube(string name, string t, int glow = 0) { Cube6(name, t, t, t, t, glow); }
    static void Cube3(string name, string top, string side, string bottom, int glow = 0) { Cube6(name, top, side, bottom, side, glow); }
    static void CubeFront(string name, string top, string side, string bottom, string front, int glow = 0) { Cube6(name, top, side, bottom, front, glow); }
    static void Cube6(string name, string top, string side, string bottom, string front, int glow) {
        if(Exists(name)) return;
        if(!Has(side) && !Has(top)) { Debug.LogWarning("TANVIIR PACK: textures missing for " + name); return; }
        Material m = Alpha(top, side, bottom, front) ? cutout : solid;
        CubeBlock b = New<CubeBlock>(name, glow);
        b.top = F(top, m); b.bottom = F(bottom, m); b.front = F(front, m); b.back = F(side, m); b.left = F(side, m); b.right = F(side, m);
        set.AddBlock(b);
    }
    static void Cross(string name, string t, int glow = 0) {
        if(Exists(name)) return;
        CrossBlock b = New<CrossBlock>(name, glow); b.face = F(t, cutout); set.AddBlock(b);
    }
    static void Fluid(string name, string t, int glow) {
        if(Exists(name)) return;
        FluidBlock b = New<FluidBlock>(name, glow); b.face = F(t, solid); set.AddBlock(b);
    }
    static void Stair(string name, string t) {
        if(Exists(name)) return;
        StairBlock b = New<StairBlock>(name, 0); b.face = F(t, Alpha(t) ? cutout : solid); set.AddBlock(b);
    }
    static void Fence(string name, string t) {
        if(Exists(name)) return;
        FenceBlock b = New<FenceBlock>(name, 0); b.face = F(t, Alpha(t) ? cutout : solid); set.AddBlock(b);
    }
    static void Pane(string name, string t) {
        if(Exists(name)) return;
        GlassBlock b = New<GlassBlock>(name, 0); b.face = F(t, cutout); set.AddBlock(b);
    }
    static void Shape(string name, TanviirPackBlock.Kind kind, string top, string side, string bottom, int glow = 0) {
        if(Exists(name)) return;
        Material m = Alpha(top, side, bottom) ? cutout : solid;
        TanviirPackBlock b = New<TanviirPackBlock>(name, glow); b.kind = kind;
        b.top = F(top, m); b.side = F(side, m); b.bottom = F(bottom, m); set.AddBlock(b);
    }

    // ------------------------------------------------------------------ old palette
    static readonly Dictionary<string, string> OldToNew = new Dictionary<string, string> {
        { "Pale Stone", "Stone" }, { "Weathered Stone", "Stone" }, { "Dark Stone", "Cobblestone" }, { "Mossy Stone", "Mossy Stone Bricks" },
        { "Warm Sandstone", "Sandstone" }, { "Ivory Brick", "End Stone" }, { "Slate", "Smooth Stone" }, { "Roof Tile", "Bricks" },
        { "Oak Beam", "Oak Log" }, { "Dark Timber", "Spruce Planks" }, { "Old Plank", "Oak Planks" }, { "Cobble", "Cobblestone" },
        { "Carved Stone", "Chiseled Stone Bricks" }, { "Gold Trim", "Gold Block" }, { "Blue Tile", "Blue Wool" }, { "Green Tile", "Green Wool" },
        { "Lava", "Orange Wool" }, { "Spawner", "Mob Spawner" }, { "Crop", "Yellow Wool" }, { "Glass Pane", "Glass" }, { "Utility Wood", "Oak Planks" },
        { "Utility Stone", "Stone" }, { "Redstone Block", "Redstone Block" }, { "Marble", "Quartz Block" }, { "Granite", "Stone" },
        { "Black Brick", "Nether Bricks" }, { "White Brick", "Quartz Block" }, { "Red Roof", "Bricks" }, { "Blue Roof", "Blue Stained Clay" },
        { "Copper Roof", "Orange Stained Clay" }, { "Timber Plaster", "White Wool" }, { "Dark Plaster", "Gray Wool" }, { "Limestone", "Smooth Stone" },
        { "Castle Wall", "Stone Bricks" }, { "Mossy Cobble", "Mossy Cobblestone" }, { "Rune Stone", "Chiseled Stone Bricks" }, { "Purple Tile", "Purple Wool" },
        { "Red Tile", "Red Wool" }, { "Gold Mosaic", "Glowstone" }, { "Iron Ore", "Iron Ore" }, { "Coal Ore", "Coal Ore" }, { "Sponge Stone", "Sponge" },
        { "Lapis Ore", "Lapis Ore" }, { "Diamond Ore", "Diamond Ore" }, { "Crystal Block", "Diamond Block" }, { "Redstone Ore", "Redstone Ore" },
        { "Clay", "Clay" }, { "Nether Brick", "Nether Bricks" }, { "Runed Stone", "Chiseled Stone Bricks" }, { "Portal Stone", "Obsidian" },
        { "Lamp Stone", "Redstone Lamp" }, { "Emerald Ore", "Emerald Ore" }, { "Emerald Block", "Emerald Block" }, { "Iron Block", "Iron Block" },
        { "Quartz", "Quartz Block" }, { "Dead Shrub", "Oak Planks" },
    };
    static string NewFor(string oldName) {
        string n = oldName.Substring("Tanviir ".Length);
        string mapped;
        if(OldToNew.TryGetValue(n, out mapped)) return mapped;
        string l = n.ToLowerInvariant();
        if(l.Contains("marble") || l.Contains("quartz") || l.Contains("white")) return "Quartz Block";
        if(l.Contains("sandstone")) return "Sandstone";
        if(l.Contains("oak") || l.Contains("timber") || l.Contains("plank") || l.Contains("wood")) return "Oak Planks";
        if(l.Contains("red roof") || l.Contains("brick")) return "Bricks";
        if(l.Contains("blue roof")) return "Blue Stained Clay";
        if(l.Contains("dark")) return "Cobblestone";
        if(l.Contains("castle") || l.Contains("granite") || l.Contains("limestone") || l.Contains("stone")) return "Stone Bricks";
        return "Stone";
    }
    static Face Copy(Face f) { return f == null ? null : new Face { material = f.material, rect = f.rect }; }
    static int RetireOldPalette() {
        int n = 0;
        List<Block> all = set.GetBlocks();
        for(int i = 0; i < all.Count; i++) {
            Block b = all[i];
            if(b == null || b.retired || !b.name.StartsWith("Tanviir ")) continue;
            Block target = set.FindBlock(Prefix + NewFor(b.name));
            Face face = target != null ? target.GetPreviewFace() : null;
            CubeBlock tc = target as CubeBlock;
            CubeBlock c = b as CubeBlock;
            if(c != null && tc != null) { c.top = Copy(tc.top); c.bottom = Copy(tc.bottom); c.front = Copy(tc.front); c.back = Copy(tc.back); c.left = Copy(tc.left); c.right = Copy(tc.right); }
            else if(c != null && face != null) { c.top = Copy(face); c.bottom = Copy(face); c.front = Copy(face); c.back = Copy(face); c.left = Copy(face); c.right = Copy(face); }
            else if(face != null) {
                if(b is StairBlock) ((StairBlock)b).face = Copy(face);
                else if(b is FenceBlock) ((FenceBlock)b).face = Copy(face);
                else if(b is TanviirArchitecturalBlock) ((TanviirArchitecturalBlock)b).face = Copy(face);
            }
            b.retired = true; n++;
        }
        return n;
    }
}
